Looks like [this](https://github.com/sockjs/sockjs-node/blob/v0.3.21/src/webjs.coffee#L45-L47) is what's triggering it.

Generated javascript is:
```js
  fake_response = function(req, res) {
    var headers;
    headers = {
      'Connection': 'close'
    };
    res.writeHead = function(status, user_headers) {
      var k, r, x;
      if (user_headers == null) {
        user_headers = {};
      }
      r = [];
      r.push('HTTP/' + req.httpVersion + ' ' + status + ' ' + http.STATUS_CODES[status]);
      utils.objectExtend(headers, user_headers);
      for (k in headers) {
        r.push(k + ': ' + headers[k]);
      }
      r = r.concat(['', '']);
      try {
        return res.write(r.join('\r\n'));
      } catch (error1) {
        x = error1;
      }
    };
    return res.setHeader = function(k, v) {
      return headers[k] = v;
    };
  };
```

There's a try catch block around the `return res.write(r.join('\r\n'));` but it still crashes nodejs for some reason.

If I remove that try catch block entirely it no longer crashes...but I don't understand why the try catch block doesn't catch the error.

Adding `res.on('error', () => {});` [fixes this](https://github.com/sockjs/sockjs-node/pull/280) in sockjs it seems.
